import numpy as np
from itertools import product

n = 24
fixed = {9: -1, 14: 1, 15: -1, 22: -1}
fixed_c = {3: 0, 9: -2, 14: -1, 19: 0}
free_pos = [i for i in range(n) if i not in fixed]

def compute_C(seq):
    return [int(np.sum(seq[:n-k] * seq[k:])) for k in range(1, n)]

# We will enumerate only 10 free variables, fix others to 1, see if we can find by trying different
# But to make it fast, let's use backtrack with pruning on the fixed C's

seq = np.zeros(n, dtype=int)
for p, v in fixed.items():
    seq[p] = v

free_pos_sorted = sorted(free_pos)

def backtrack(index):
    if index == len(free_pos_sorted):
        C = compute_C(seq)
        if all(C[k-1] == v for k,v in fixed_c.items()):
            s = sum(c*c for c in C)
            if s <= 62:
                return True, seq.tolist(), s, C
        return False, None, None, None
    pos = free_pos_sorted[index]
    for val in [-1, 1]:
        seq[pos] = val
        # check if any fixed C can be violated already
        can_prune = False
        for k, target in fixed_c.items():
            # if all positions for this C_k are filled, check
            filled = True
            s = 0
            for i in range(n - k):
                if seq[i] == 0 or seq[i+k] == 0:
                    filled = False
                    break
                s += seq[i] * seq[i+k]
            if filled and s != target:
                can_prune = True
                break
        if not can_prune:
            found, sol, merit, Cs = backtrack(index + 1)
            if found:
                return True, sol, merit, Cs
    seq[pos] = 0
    return False, None, None, None

